using System;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using TMPro;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
public static class CheckShowcaseMenuFlow{
static async Task Frames(int n){for(int i=0;i<n;i++){EditorApplication.Step();await Task.Delay(25);}}
static void Require(bool condition,string message){if(!condition)throw new Exception(message);}
static GameObject Panel(VehicleShowcaseManager m,string field)=>(GameObject)new SerializedObject(m).FindProperty(field).objectReferenceValue;
static void Click(GameObject panel,string path)=>panel.transform.Find(path).GetComponent<UnityEngine.UI.Button>().onClick.Invoke();
static void Fit(GameObject panel){foreach(var text in panel.GetComponentsInChildren<TMP_Text>()){text.ForceMeshUpdate();Require(!text.isTextOverflowing,"Text overflow: "+panel.name+"/"+text.name+" "+text.text);}}
static async Task Escape(){UnityEngine.Object.FindAnyObjectByType<VehicleShowcaseManager>().NavigateBack();await Frames(2);}
public static async Task<string> Navigate(){await Frames(4);int frame=Time.frameCount;var m=UnityEngine.Object.FindAnyObjectByType<VehicleShowcaseManager>();var courses=Panel(m,"courseSelectionPanel");var modes=Panel(m,"driveModePanel");var challenges=Panel(m,"challengePanel");
var drive=GameObject.Find("DriveButton").GetComponent<UnityEngine.UI.Button>();drive.onClick.Invoke();await Frames(2);Require(courses.activeSelf&&!modes.activeSelf,"Drive must open courses first");Fit(courses);var original=GameObject.Find("VehicleNameText").GetComponent<TMP_Text>().text;m.ShowNextVehicle();Require(GameObject.Find("VehicleNameText").GetComponent<TMP_Text>().text==original,"Vehicle changed behind menu");
string[] names={"TestCircuitCourse","LakeTownCourse","MountainPassCourse","HarborStreetCourse"};
for(int i=0;i<names.Length;i++){Click(courses,"Dialog/"+names[i]);Click(courses,"Dialog/Night");Click(courses,"Dialog/Go");await Frames(2);Require(modes.activeSelf&&!courses.activeSelf,"Next must open modes");Require((int)m.FreeRideCourse==i&&m.FreeRideLighting==TestDriveSelection.TimeOfDay.Night,"Lost selection");Require(modes.transform.Find("Dialog/ChallengeButton").GetComponent<UnityEngine.UI.Button>().interactable==(i==0),"Wrong challenge availability");Fit(modes);
if(i==0){Click(modes,"Dialog/ChallengeButton");await Frames(2);Require(challenges.activeSelf&&!modes.activeSelf,"Existing circuit challenges unavailable");Fit(challenges);await Escape();Require(modes.activeSelf&&!challenges.activeSelf,"Challenge Escape must return to modes");}
if(i%2==0)await Escape();else Click(modes,"Dialog/BackButton");await Frames(2);Require(courses.activeSelf&&!modes.activeSelf,"Back must return to courses");Require((int)m.FreeRideCourse==i&&m.FreeRideLighting==TestDriveSelection.TimeOfDay.Night,"Back lost selection");}
await Escape();Require(!courses.activeSelf&&!modes.activeSelf&&drive.interactable,"Course Escape must restore showroom");drive.onClick.Invoke();await Frames(2);Click(courses,"Dialog/Back");Require(!courses.activeSelf&&drive.interactable,"Course Back must restore showroom");drive.onClick.Invoke();Click(courses,"Dialog/HarborStreetCourse");Click(courses,"Dialog/Go");await Frames(2);
Require(Time.frameCount>frame,"Frames not advancing");return "All four courses: correct panel order, selected course/night retained, Next does not launch, Back buttons and Escape navigation handler retrace flow, vehicle controls locked/restored, existing Test Circuit challenges available, other challenges safely deferred; visible text fits. Frames="+frame+" -> "+Time.frameCount;}
public static async Task<string> Launches(){var results=new List<string>();string[] names={"TestCircuitCourse","LakeTownCourse","MountainPassCourse","HarborStreetCourse"};string[] scenes={"TestTrackScene","LakeTownScene","MountainPassScene","HarborStreetScene"};
try{for(int i=0;i<names.Length;i++){Time.timeScale=1;SceneManager.LoadScene("ShowcaseScene");await Frames(5);var m=UnityEngine.Object.FindAnyObjectByType<VehicleShowcaseManager>();var courses=Panel(m,"courseSelectionPanel");var modes=Panel(m,"driveModePanel");GameObject.Find("DriveButton").GetComponent<UnityEngine.UI.Button>().onClick.Invoke();Click(courses,"Dialog/"+names[i]);Click(courses,i%2==0?"Dialog/Day":"Dialog/Night");Click(courses,"Dialog/Go");await Frames(2);Require(SceneManager.GetActiveScene().name=="ShowcaseScene","Next launched prematurely");if(i==3)Time.timeScale=0;Click(modes,"Dialog/FreeRunButton");Click(modes,"Dialog/FreeRunButton");m.BackToCourses();Require(!courses.activeSelf,"Back bypassed transition lock");Require(SceneManager.GetActiveScene().name=="ShowcaseScene","Audio delay bypassed");for(int n=0;n<200&&SceneManager.GetActiveScene().name=="ShowcaseScene";n++)await Frames(1);Require(SceneManager.GetActiveScene().name==scenes[i],"Wrong launched scene "+i);Require((int)TestDriveSelection.Course==i&&TestDriveSelection.IsNight==(i%2==1),"Wrong drive selection");results.Add(scenes[i]+" "+TestDriveSelection.Lighting+(i==3?" (paused time transition passed)":""));}}
finally{Time.timeScale=1;SceneManager.LoadScene("ShowcaseScene");await Frames(4);}return "Free Run launches passed, duplicate-click and audio-delay guards retained: "+string.Join("; ",results);}
}
